import{_ as t,o as a,c as r,a0 as i}from"./chunks/framework.Czf8PZMA.js";const g=JSON.parse('{"title":"Modular Housing for the U.S. (California) Market — Framework & Operating Manual","description":"","frontmatter":{},"headers":[],"relativePath":"guide/en-overview.md","filePath":"guide/en-overview.md","lastUpdated":null}'),o={name:"guide/en-overview.md"};function n(s,e,l,c,d,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="modular-housing-for-the-u-s-california-market-—-framework-operating-manual" tabindex="-1">Modular Housing for the U.S. (California) Market — Framework &amp; Operating Manual <a class="header-anchor" href="#modular-housing-for-the-u-s-california-market-—-framework-operating-manual" aria-label="Permalink to &quot;Modular Housing for the U.S. (California) Market — Framework &amp; Operating Manual&quot;">​</a></h1><h3 id="executive-summary-交付包总览-·-english-overview" tabindex="-1">Executive Summary（交付包总览 · English Overview） <a class="header-anchor" href="#executive-summary-交付包总览-·-english-overview" aria-label="Permalink to &quot;Executive Summary（交付包总览 · English Overview）&quot;">​</a></h3><p><strong>Prepared by:</strong> Modular-Agent（modular housing knowledge specialist） <strong>Scope:</strong> Complete technical + compliance framework and operating manual for Chinese Modular Housing suppliers entering the <strong>California</strong> market, benchmarked to U.S. (ASTM/AISC/NDS/ACI/NFPA/UL) and Federal (HUD/FHA/ADA/OSHA) standards, with <strong>US↔China standard correspondence</strong> for domestic factory alignment.</p><hr><h2 id="_1-what-this-package-is" tabindex="-1">1. What This Package Is <a class="header-anchor" href="#_1-what-this-package-is" aria-label="Permalink to &quot;1. What This Package Is&quot;">​</a></h2><p>A 7-part deliverable set that functions as both a <strong>global operating manual</strong> and <strong>per-structural-type spec templates</strong>. It answers: <em>what technical/process requirements apply globally, which sections are shared vs. type-specific, and how to write each SECTION to US spec with CN correspondence.</em></p><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td>00</td><td><strong>Operating Manual</strong> — CA FBH compliance workflow, 6 Gates, shared-vs-specific chapter matrix, document/authority list, usage sequence</td></tr><tr><td>01</td><td><strong>Shared framework base</strong> — Div 00/01/07/13(generic)/21-28/31-33/48 + §0.4 CA+Federal standards-distribution matrix</td></tr><tr><td>02</td><td><strong>Steel template</strong> — Div 03/05/13/16 (A992/A36, AISC 360, AWS D1.1/D1.8)</td></tr><tr><td>03</td><td><strong>Concrete/UHPC template</strong> — Div 03/13 (ACI 318, ESR-5874 UHPC)</td></tr><tr><td>04</td><td><strong>Wood template</strong> — Div 06/09/13 (NDS/WFCM/PRG-320 CLT)</td></tr><tr><td>05</td><td><strong>US supplier SPEC practices benchmark</strong> — 14+ active suppliers (Boxabl/Stack/CIMC-MBS/Plant Prefab…)</td></tr><tr><td>06</td><td><strong>Materials/equipment list with US↔CN correspondence</strong> (GB/T ↔ ASTM/AISC) + 07</td></tr></tbody></table><hr><h2 id="_2-global-compliance-pathway-all-types" tabindex="-1">2. Global Compliance Pathway (All Types) <a class="header-anchor" href="#_2-global-compliance-pathway-all-types" aria-label="Permalink to &quot;2. Global Compliance Pathway (All Types)&quot;">​</a></h2><p><strong>California FBH path (primary):</strong> Product type → <strong>DAA</strong> delegated design approval (CA licensed SE) → <strong>QAA/HCD</strong> factory inspection (Title 25 §3032: 100%→first 10 units→25%) → <strong>HCD insignia</strong> (HSC §19980) → local AHJ permit/install/CO → delivery (SB 800 warranty). Dual-track: HCD governs factory product+quality; local AHJ governs site install+occupancy.</p><p><strong>Six Gates (G1-6):</strong> Compliance path lock → design freeze (DAA) → production start (FQP) → module ex-factory release (FAT/insignia/triple-release) → site structural closeout → occupancy/CO.</p><p><strong>Federal layer (overlay, not replacement):</strong> HUD 24 CFR 3280 (optional, default excluded), FHA/HUD MPS, ADA 2010 + CA Ch.11B, Fair Housing, Lead 40 CFR 745, OSHA 29 CFR 1910/1926, import compliance (ISPM-15 timber, steel tariffs).</p><hr><h2 id="_3-shared-vs-type-specific-chapters" tabindex="-1">3. Shared vs. Type-Specific Chapters <a class="header-anchor" href="#_3-shared-vs-type-specific-chapters" aria-label="Permalink to &quot;3. Shared vs. Type-Specific Chapters&quot;">​</a></h2><p><strong>Shared (in 01 + 06):</strong> Div 00 procurement / 01 general(submittals-QA-QC-rigging-execution-closeout) / 07 envelope / 13 generic module core / 14 vertical transport / 21-28 MEP interface language / 31-33 site / 48 PV + materials list(CN↔US).</p><p><strong>Type-specific (each template only):</strong></p><ul><li><strong>Steel (02):</strong> Div 05 12/31/50 + steel module FAT/SAT</li><li><strong>Concrete/UHPC (03):</strong> Div 03 10/33 + 13 34 23 (ESR-5874)</li><li><strong>Wood (04):</strong> Div 06 05/10/13/16/17/20 + Div 09 fire separation</li></ul><hr><h2 id="_4-us↔china-standard-correspondence-key-differentiator-for-chinese-suppliers" tabindex="-1">4. US↔China Standard Correspondence（Key Differentiator for Chinese Suppliers） <a class="header-anchor" href="#_4-us↔china-standard-correspondence-key-differentiator-for-chinese-suppliers" aria-label="Permalink to &quot;4. US↔China Standard Correspondence（Key Differentiator for Chinese Suppliers）&quot;">​</a></h2><p>Each material carries a <strong>US baseline (enforceable) + CN equivalent (for factory alignment)</strong>. Examples: Q355→A992, Q235→A36, GB 50017↔AISC 360+GB 50011↔AISC 341, GB/T 13912↔ASTM A123/A153 galvanizing, GB 8624-2008↔ASTM E84 fire class, GB/T 6952↔ASME A112.19/WaterSense fixtures, GB/T 26899↔PRG-320 CLT, ESR-5874↔T/CECS UHPC. <strong>Principle:</strong> US standard = sole acceptance baseline; CN standard = production/cost alignment only; differences (impact toughness, coating thickness, fire class, water efficiency) documented item-by-item.</p><hr><h2 id="_5-ready-to-use-deliverables-for-the-supply-chain" tabindex="-1">5. Ready-to-Use Deliverables for the Supply Chain <a class="header-anchor" href="#_5-ready-to-use-deliverables-for-the-supply-chain" aria-label="Permalink to &quot;5. Ready-to-Use Deliverables for the Supply Chain&quot;">​</a></h2><ul><li><strong>06 materials/equipment list</strong> → write each &quot;Products/Materials&quot; subsection with US performance + CN correspondence.</li><li><strong>07 full SECTION 05 12 00</strong> → production-ready MasterFormat 3-part spec with material substitution table (CN↔US), measurable acceptance criteria, and 3 hold points (HP-1 ex-factory/FAT, HP-2 pre-connection, HP-3 post-connection before conceal) mapped to Gates 4/5.</li><li>Same 3-part template applies to every SECTION across all three structural types.</li></ul><h2 id="_6-platform-live-radar-forward-direction" tabindex="-1">6. Platform &amp; Live Radar (Forward Direction) <a class="header-anchor" href="#_6-platform-live-radar-forward-direction" aria-label="Permalink to &quot;6. Platform &amp; Live Radar (Forward Direction)&quot;">​</a></h2><p>This framework is the <strong>seed content for an open platform</strong> serving Chinese modular integrators and trade suppliers entering the U.S. market. Platform layers:</p><ul><li><strong>L1 Knowledge Base</strong>: integrates the master spec-agent library (Modular Housing = a specialized view of it) + these deliverables.</li><li><strong>L2 Live Radar</strong>: per-category competitor benchmarking (each category&#39;s most advanced benchmark, dynamically refreshed) + standard/code change tracking (IBC/CBC/ASCE 7/AISC/NDS/ACI/ASTM/ICC-ES ESR, HCD Title 25, tariffs); tracking-list released, cron auto-reporting next.</li><li><strong>L3 Advisory/Tech-justification services</strong>: product US-standard review, spec deepening, <strong>approval-process pathways</strong>, and <strong>lifecycle stakeholder roles/responsibilities/obligations</strong>.</li><li><strong>L4 Ops hub</strong>: distills accumulated knowledge; selectively publishes items tagged <strong>Modular House</strong> from the knowledge-channel building graph.</li></ul><p><strong>Build approach:</strong> static site first, Chinese-primary with i18n English toggle reserved; public (no membership); tracking-list-first → then cron automation.</p><hr><p><em>Contact: Modular-Agent · 模块化住房知识库. Background batch ingestion of source library is ongoing; specific model/part numbers from the parsed CBOM will be back-filled into the materials list when OCR completes.</em></p>',29)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
